    "refs.sub": "Every check follows a published protocol. None of them diagnose anything on their own — they exist so you arrive at your appointment prepared.",
    "refs.snellen.t": "Snellen acuity",
    "refs.snellen.b": "Letters sized so the whole optotype subtends five arc-minutes at the test distance — the 1862 standard every testing center still uses.",
    "refs.ishihara.t": "Ishihara plates",
    "refs.ishihara.b": "Screening plates inspired by Ishihara principles that check red-green colour distinction — not a clinical Ishihara test.",
    "refs.duochrome.t": "Duochrome & dial",
    "refs.duochrome.b": "The red/green balance and the astigmatic dial screen spherical and cylindrical error before anyone measures a prescription.",
    "refs.jaeger.t": "Jaeger near card",
    "refs.jaeger.b": "Reading text from 40 cm — the near point a counter form assumes when it hands you a clipboard.",
    "refs.sources": "Sources & further reading",
    "refs.dmv": "Official licensing agencies",
    "refs.learn": "Method",
    "states.official": "Official site",
    "faq.q9": "What is the duochrome test?",
    "faq.a9": "The same letters are shown on a red and a green background. If they look sharper on red, your eye is focusing slightly in front of the retina (short-sight); on green, slightly behind (long-sight). Opticians have used it for a century to fine-tune a prescription.",
    "faq.q10": "Can this tell me my prescription?",
    "faq.a10": "No. The refraction and astigmatism checks give a screening hint about the direction of any error, and nothing more. Only a qualified optometrist with a phoropter and trial lenses can issue a prescription.",
    "faq.q11": "Why can I not see the hidden shape?",
    "faq.a11": "About one person in ten cannot free-view an autostereogram, and it also fails if one eye is much stronger than the other or if you cannot fuse the two images. Not seeing the shape is not by itself a diagnosis — but it is worth mentioning at your next eye exam.",
    "faq.q12": "What happens if you fail the eye test at the DMV?",
    "faq.a12": "You do not lose your license on the spot. The examiner hands you a form for an eye doctor (California DL-62, New York MV-619, Florida HSMV-72010 and Texas DL-63 are common examples), you get your eyes checked, and you come back to retake the vision screening.",
    "faq.q13": "Can I wear my glasses or contacts for the test?",
    "faq.a13": "Yes, and you should. Wear whatever you drive in. The catch is that passing with correction adds a corrective-lenses restriction to your license. Reading glasses alone rarely help, because the test measures distance vision, not reading vision.",
    "faq.q14": "What does the DMV eye test look like?",
    "faq.a14": "Most offices use a desktop viewer such as the Optec 1000 or Titmus V1. You rest your forehead against it and read lines of letters or numbers on small slides inside, one eye at a time. The examiner may ask you to read one numbered line fully, then move to the next, and finish with flashes at the sides plus a red, green and amber colour check.",
    "faq.q15": "Can I take the DMV eye test online?",
    "faq.a15": "No, with one exception. New York accepts results through its Online Vision Registry from approved providers. Everywhere else the official screening happens in person, so an online test is practice only.",
    "faq.q16": "What should I bring if my vision might fail?",
    "faq.a16": "Your glasses or contacts, your current prescription if you have one, and your ID. If you already failed once, bring the completed doctor form your state asked for. New York also accepts an optometrist report on form MV-619 instead of a counter reading.",
    "faq.q17": "How to pass the DMV eye test?",
    "faq.a17": "Learn the procedure, not the poster. Offices rotate charts and the letters change, so memorising one chart buys you nothing. Practising with randomised letters, the way this screener does it, is the only rehearsal that transfers.",
    "faq.q18": "Why do I cover one eye when I drive with both open?",
    "faq.a18": "Because most states set a standard per eye as well as for both together. One weak eye can hide behind a strong one when both are open, so the examiner checks each eye separately first and both together last.",
    "faq.q19": "What restrictions can end up on my license?",
    "faq.a19": "The common ones are corrective lenses, daylight-only driving and outside mirrors. Texas adds a 45 mph limit to its daylight restriction for the 20/60 to 20/70 band. The code is printed on the license itself.",
    "faq.q20": "How do I get a glasses restriction removed?",
    "faq.a20": "Pass the screening without correction at a later visit, or after surgery such as LASIK. In New York you can also submit a fresh passing result through the Online Vision Registry instead of queuing at an office.",
    "faq.q21": "What visual acuity is required to pass the DMV eye test?",
    "faq.a21": "Most US states require 20/40 visual acuity in each eye or in both eyes combined for an unrestricted license. Vision between 20/40 and 20/70 typically qualifies for daytime or corrective lens restrictions with medical clearance.",
    "faq.q22": "What happens if I fail the eye test at the DMV counter?",
    "faq.a22": "Failing does not cancel your license on the spot. The examiner issues a vision referral form for a licensed optometrist or ophthalmologist to complete. Once signed and updated, you return to complete the screening.",
    "faq.q23": "Does the DMV test peripheral vision and how much is required?",
    "faq.a23": "Yes, most states test horizontal peripheral awareness using flashing lights in the machine, typically requiring a total field between 110° and 140° across both eyes (or at least 70° to 80° in one eye).",
    "gen.hero.title": "Check your <em>vision online</em>, eye by eye.",
    "gen.hero.lede": "Calibrate your screen, stand at the right distance, cover one eye at a time and read the smallest line you can. 12 vision checks, eye by eye, in about ten minutes.",
    "gen.checks.title": "12 checks for distance, colour and near vision",
