    "faq.q13": "¿Puedo usar gafas o lentes de contacto en la prueba?",
    "faq.a13": "Sí, y debes hacerlo. Usa lo que usas para conducir. La trampa es que aprobar con corrección añade una restricción de lentes correctivas a tu licencia.",
    "faq.q14": "¿Cómo es la máquina del examen de la vista del DMV?",
    "faq.a14": "La mayoría de las oficinas usan un visor de escritorio. Apoyas la frente y lees líneas de letras por dentro, un ojo a la vez.",
    "faq.q15": "¿Puedo hacer el examen de la vista del DMV en línea?",
