    "featured.badge": "Guía destacada",
    "profesional.kicker": "Conductores profesionales",
    "profesional.title": "Preparación de visión para profesional y transporte",
    "profesional.body": "Las licencias comerciales interestatales siguen una norma federal más estricta que una licencia normal: agudeza en cada ojo por separado, un mínimo de campo visual y distinguir el rojo del verde. Practica los tres antes de tu examen médico.",
    "profesional.l1": "Agudeza corregida en cada ojo y con ambos a la vez",
    "profesional.l2": "Campo visual en el ojo peor",
    "profesional.l3": "Reconocer el rojo, el verde y el ámbar del tráfico",
    "profesional.cta": "Hacer el conjunto profesional",
    "profesional.cardTitle": "Practica el conjunto federal",
    "profesional.cardBody": "Agudeza por ojo, una E tumbling para el campo visual y la serie de color, en una sola secuencia.",
    "faq.kicker": "Preguntas",
    "faq.title": "Antes de empezar",
    "faq.q1": "¿Cuenta como examen oficial?",
    "faq.a1": "No. Es una evaluación de práctica para que llegues preparado. La prueba oficial la hace un empleado con su propio equipo, y solo esa cuenta.",
    "faq.q2": "¿Puede sustituir una visita al optometrista?",
    "faq.a2": "No. Nada en una pantalla puede diagnosticar ni graduar. Si los resultados te preocupan, ve a un optometrista.",
    "faq.q3": "¿Qué agudeza necesito para conducir?",
    "faq.a3": "En casi todos los estados, 20/40 o mejor con los dos ojos para una licencia sin restricciones. Muchos permiten conducir con espejos hasta 20/70.",
    "faq.q4": "¿Debo llevar gafas o lentillas?",
    "faq.a4": "Sí. Haz la prueba con la corrección que usas al conducir: el centro evalúa la visión corregida y la licencia llevará la restricción correspondiente.",
    "faq.q5": "¿Por qué hay que calibrar la pantalla?",
    "faq.a5": "El tamaño de las letras se calcula en milímetros. Sin calibrar, un 20/40 en tu monitor no es un 20/40 real. Una tarjeta bancaria basta para ajustar la escala.",
    "faq.q6": "¿A qué distancia debo sentarme?",
    "faq.a6": "Tres metros caben en casi cualquier habitación; seis metros son el estándar de Snellen. Lo importante es medir una vez y volver siempre al mismo punto.",
    "faq.q7": "¿Qué es la prueba de la E tumbling?",
    "faq.a7": "Una E cuya abertura apunta en una de cuatro direcciones. En vez de nombrar letras, dices hacia dónde apunta. Se usa con quien no lee el alfabeto latino y en muchos exámenes de profesional.",
    "faq.q8": "¿Se guardan mis resultados en algún sitio?",
    "faq.a8": "Solo en este navegador. No hay cuentas ni subidas. Puedes borrarlos cuando quieras.",
    "footer.tagline": "Una evaluación de visión gratuita para revisar tu vista en casa.",
    "footer.langs": "Disponible en inglés, español, francés, alemán, portugués, italiano, japonés y ruso.",
