    "footer.p1": "Sin cuentas, sin subidas. Los resultados se guardan en el propio almacenamiento de este navegador y se pueden borrar en cualquier momento.",
    "footer.disclaimer": "Las pantallas pequeñas o una distancia de visualización incorrecta pueden provocar errores. Para obtener resultados precisos, consulta a un profesional de la visión.",
    "footer.copy": "Online Vision Test. Evaluación de práctica, uso gratuito.",
    "featured.CA": "Seis meses de plazo para nuevos residentes; la revisión al renovar es rápida y puede hacerse en un kiosco.",
    "featured.FL": "Prueba de visión en cada renovación, pero sirve el informe del médico. Se permiten espejos hasta 20/70.",
    "featured.IL": "Se evalúa cada ojo por separado y, si fallas, te envían a un informe médico.",
    "featured.NY": "Se prueba con los dos ojos abiertos. Hasta 20/70 puedes obtener licencia con espejos instalados.",
