    "states.official": "Sitio oficial",
    "faq.q9": "¿Qué es la prueba duocroma?",
    "faq.a9": "Se muestran las mismas letras sobre fondo rojo y verde. Si se ven más nítidas sobre rojo, tu ojo enfoca ligeramente por delante de la retina (miopía); sobre verde, por detrás (hipermetropía). Los ópticos la usan desde hace un siglo para ajustar la graduación.",
    "faq.q10": "¿Puede decirme mi graduación?",
    "faq.a10": "No. Las pruebas de refracción y astigmatismo solo orientan sobre la dirección del error, nada más. Solo un optometrista titulado con foróptero y lentes de prueba puede recetar.",
    "faq.q11": "¿Por qué no veo la figura escondida?",
    "faq.a11": "Cerca de una de cada diez personas no puede ver estos estereogramas, y también falla si un ojo es mucho más fuerte que el otro o si no puedes fusionar las dos imágenes. No verla no es un diagnóstico por sí mismo, pero conviene mencionarlo en tu próxima revisión.",
    "checks.amsler.name": "Rejilla de Amsler",
    "checks.amsler.desc": "Comprueba la degeneración macular: busca líneas onduladas, rotas o ausentes.",
    "amsler.title": "Rejilla de Amsler",
    "amsler.sub": "Mantén la pantalla a una distancia de lectura normal. Cúbrete un ojo, mira el punto y observa las líneas de la cuadrícula.",
