    "faq.q1": "Est-ce un examen officiel du centre ?",
    "faq.a1": "Non. C'est une évaluation d'entraînement, pour arriver préparé. Le contrôle officiel est fait par un agent du centre avec son propre matériel, et lui seul compte.",
    "faq.q2": "Cela remplace-t-il une visite chez l'optométriste ?",
    "faq.a2": "Non. Rien sur un écran ne peut diagnostiquer ou prescrire. Si les résultats vous inquiètent, consultez un optométriste.",
    "faq.q3": "Quelle acuité faut-il pour conduire ?",
    "faq.a3": "Dans presque tous les États, 20/40 ou mieux des deux yeux pour un permis sans restriction. Beaucoup autorisent la conduite avec rétroviseurs jusqu'à 20/70.",
    "faq.q4": "Faut-il porter ses lunettes ou lentilles ?",
    "faq.a4": "Oui. Testez avec la correction que vous utilisez au volant : le centre évalue la vision corrigée et le permis portera la restriction correspondante.",
    "faq.q5": "Pourquoi calibrer l'écran ?",
    "faq.a5": "La taille des lettres se calcule en millimètres. Sans calibration, un 20/40 affiché n'est pas un vrai 20/40. Une carte bancaire suffit à régler l'échelle.",
    "faq.q6": "À quelle distance faut-il s'asseoir ?",
    "faq.a6": "Trois mètres conviennent à la plupart des pièces ; six mètres sont la norme de Snellen. L'essentiel est de mesurer une fois et de revenir toujours au même endroit.",
    "faq.q7": "Qu'est-ce que le test de l'E tournant ?",
    "faq.a7": "Un E dont l'ouverture pointe dans l'une des quatre directions. Au lieu de nommer des lettres, vous indiquez la direction. Il sert pour ceux qui ne lisent pas l'alphabet latin, et dans de nombreux examens profesional.",
    "faq.q8": "Mes résultats sont-ils stockés quelque part ?",
    "faq.a8": "Uniquement dans ce navigateur. Aucun compte, aucun envoi. Vous pouvez les effacer quand vous voulez.",
    "footer.tagline": "Une évaluation de vision gratuite pour vérifier votre vue à la maison.",
