    "faq.q9": "Qu'est-ce que le test duochrome ?",
    "faq.a9": "Les mêmes lettres sont affichées sur fond rouge et vert. Si elles paraissent plus nettes sur le rouge, votre œil fait la mise au point légèrement en avant de la rétine (myopie) ; sur le vert, en arrière (hypermétropie). Les opticiens l'utilisent depuis un siècle pour affiner une correction.",
    "faq.q10": "Pouvez-vous me donner ma correction ?",
    "faq.a10": "Non. Les contrôles de réfraction et d'astigmatisme donnent seulement une indication sur la direction de l'erreur. Seul un optométriste qualifié, avec un réfracteur et des verres d'essai, peut établir une ordonnance.",
    "faq.q11": "Pourquoi je ne vois pas la forme cachée ?",
    "faq.a11": "Environ une personne sur dix ne peut pas voir ces autostéréogrammes, et cela échoue aussi si un œil est bien plus fort que l'autre ou si vous ne fusionnez pas les deux images. Ne pas voir la forme n'est pas un diagnostic en soi, mais cela vaut la peine d'être signalé lors de votre prochain examen.",
