    "featured.badge": "Hervorgehobener Steckbrief",
    "profesional.kicker": "Berufskraftfahrer",
    "profesional.title": "Sehtest-Vorbereitung für profesional und transporte",
    "profesional.body": "Bundesweite gewerbliche Führerscheine unterliegen einer strengeren Norm als der normale Führerschein: Sehschärfe je Auge einzeln, ein Mindest-Gesichtsfeld und die Fähigkeit, Rot von Grün zu unterscheiden. Übe alle drei vor dem Untersuchungstermin.",
    "profesional.l1": "Korrigierte Sehschärfe je Auge und mit beiden zusammen",
    "profesional.l2": "Gesichtsfeld im schlechteren Auge",
    "profesional.l3": "Verkehrsrot, Grün und Gelb erkennen",
    "profesional.cta": "profesional-Set starten",
    "profesional.cardTitle": "Das bundesweite Set üben",
    "profesional.cardBody": "Sehschärfe je Auge, ein Tumbling-E für das Gesichtsfeld und die Farbtafeln — in einer Reihenfolge.",
    "faq.kicker": "Fragen",
    "faq.title": "Bevor du beginnst",
    "faq.q1": "Zählt das als offizieller Test?",
    "faq.a1": "Nein. Es ist ein Übungstest, damit du vorbereitet ankommst. Den offiziellen Test macht ein Mitarbeiter mit eigener Ausrüstung — nur der zählt.",
    "faq.q2": "Ersetzt das den Besuch beim Optiker?",
    "faq.a2": "Nein. Nichts auf einem Bildschirm kann diagnostizieren oder ein Rezept ausstellen. Wenn dich die Ergebnisse beunruhigen, geh zum Optiker.",
    "faq.q3": "Welche Sehschärfe brauche ich zum Fahren?",
    "faq.a3": "In fast allen Bundesstaaten 20/40 oder besser mit beiden Augen für den Führerschein ohne Auflagen. Viele erlauben mit Spiegeln noch 20/70.",
    "faq.q4": "Soll ich Brille oder Kontaktlinsen tragen?",
    "faq.a4": "Ja. Teste mit der Korrektur, mit der du fährst — das Amt prüft die korrigierte Sehschärfe und der Führerschein bekommt den passenden Vermerk.",
    "faq.q5": "Warum muss ich den Bildschirm kalibrieren?",
    "faq.a5": "Die Buchstabengrößen werden in Millimetern berechnet. Unkalibriert ist ein 20/40-Buchstabe am Monitor kein echtes 20/40. Eine Bankkarte reicht zum Einstellen.",
    "faq.q6": "Wie weit weg soll ich sitzen?",
    "faq.a6": "Drei Meter passen in die meisten Räume, sechs Meter sind die Snellen-Norm. Wichtig ist, einmal zu messen und immer am selben Platz zu stehen.",
    "faq.q7": "Was ist der Tumbling-E-Test?",
    "faq.a7": "Ein E, dessen Öffnung in eine von vier Richtungen zeigt. Statt Buchstaben zu nennen, sagst du die Richtung. Er wird für Menschen ohne lateinisches Alphabet und in vielen profesional-Prüfungen genutzt.",
    "faq.q8": "Werden meine Ergebnisse irgendwo gespeichert?",
    "faq.a8": "Nur in diesem Browser. Keine Konten, keine Uploads. Du kannst sie jederzeit löschen.",
    "footer.tagline": "Ein kostenloser Sehtest, um deine Augen zu Hause zu prüfen.",
    "footer.langs": "Verfügbar in Englisch, Spanisch, Französisch, Deutsch, Portugiesisch, Italienisch, Japanisch und Russisch.",
