    "footer.p1": "Kein Konto, keine Uploads. Die Ergebnisse werden im eigenen Speicher dieses Browsers aufbewahrt und können jederzeit gelöscht werden.",
    "footer.disclaimer": "Kleine Bildschirme oder ein falscher Betrachtungsabstand können zu Fehlern führen. Für genaue Ergebnisse wenden Sie sich bitte an einen Augenarzt oder Optiker.",
    "footer.copy": "Online Vision Test. Übungstest, kostenlos nutzbar.",
    "featured.CA": "Sechs Monate Übergangsfrist für neue Einwohner; der Sehtest bei der Verlängerung ist schnell und am Kiosk möglich.",
    "featured.FL": "Sehtest bei jeder Verlängerung, das Arztformular genügt. Spiegel bis 20/70 erlaubt.",
    "featured.IL": "Jedes Auge wird einzeln geprüft; bei Nichtbestehen folgt ein Arztbericht.",
    "featured.NY": "Geprüft mit beiden Augen offen. Bis 20/70 ist der Führerschein mit Spiegeln möglich.",
    "featured.TX": "Jedes Auge einzeln, mit eingeschränkter Option bis 20/70 bei Sehhilfe.",
    "featured.NC": "Beim Verlängern wird das bessere Auge geprüft; Spiegel halten den Führerschein bis 20/70 gültig.",
    "featured.SC": "20/40 im besseren Auge bei der Verlängerung oder ein Arztzeugnis — kaum Spielraum.",
