    "faq.q9": "Was ist der Duochromtest?",
    "faq.a9": "Dieselben Buchstaben erscheinen auf rotem und grünem Hintergrund. Wirken sie auf Rot schärfer, fokussiert Ihr Auge etwas vor der Netzhaut (Kurzsichtigkeit); auf Grün dahinter (Weitsichtigkeit). Optiker nutzen ihn seit einem Jahrhundert zum Feinabstimmen einer Korrektur.",
    "faq.q10": "Kann ich hier meine Sehstärke erfahren?",
    "faq.a10": "Nein. Refraktion und AstigmatismUhr geben nur einen Hinweis auf die Richtung eines Fehlers, mehr nicht. Nur eine qualifizierte Optometristin mit Phoropter und Messgläsern kann ein Rezept ausstellen.",
    "faq.q11": "Warum sehe ich die versteckte Form nicht?",
    "faq.a11": "Etwa eine von zehn Personen kann solche Autostereogramme nicht sehen; es scheitert auch, wenn ein Auge viel stärker ist als das andere oder Sie die beiden Bilder nicht verschmelzen können. Die Form nicht zu sehen ist für sich keine Diagnose — aber ein guter Hinweis für die nächste Augenuntersuchung.",
