    "featured.badge": "Guia em destaque",
    "profesional.kicker": "Motoristas profissionais",
    "profesional.title": "Preparação de visão para profesional e transporte",
    "profesional.body": "Habilitações comerciais interestaduais seguem um padrão federal mais rígido que a comum: acuidade em cada olho separadamente, um mínimo de campo visual e saber diferenciar vermelho de verde. Treine os três antes do exame médico.",
    "profesional.l1": "Acuidade corrigida em cada olho e nos dois juntos",
    "profesional.l2": "Campo visual no pior olho",
    "profesional.l3": "Reconhecer o vermelho, o verde e o âmbar do trânsito",
    "profesional.cta": "Fazer o conjunto profesional",
    "profesional.cardTitle": "Treine o conjunto federal",
    "profesional.cardBody": "Acuidade por olho, uma E giratória para o campo visual e a série de cores — em uma única sequência.",
    "faq.kicker": "Perguntas",
    "faq.title": "Antes de começar",
    "faq.q1": "Isso vale como exame oficial?",
    "faq.a1": "Não. É um teste de treino para você chegar preparado. O exame oficial é feito por um atendente do centro com o equipamento dele, e só esse resultado conta.",
    "faq.q2": "Substitui uma consulta com optometrista?",
    "faq.a2": "Não. Nada em uma tela pode diagnosticar ou receitar. Se os resultados preocupam, procure um optometrista.",
    "faq.q3": "Que acuidade eu preciso para dirigir?",
    "faq.a3": "Em quase todos os estados, 20/40 ou melhor com os dois olhos para a habilitação sem restrição. Muitos ainda habilitam com espelhos até 20/70.",
    "faq.q4": "Devo usar óculos ou lentes?",
    "faq.a4": "Sim. Faça o teste com a correção que você usa ao dirigir: o centro avalia a visão corrigida e a habilitação trará a restrição correspondente.",
    "faq.q5": "Por que preciso calibrar a tela?",
    "faq.a5": "O tamanho das letras é calculado em milímetros. Sem calibrar, um 20/40 no monitor não é um 20/40 real. Um cartão bancário basta para ajustar a escala.",
    "faq.q6": "A que distância devo sentar?",
    "faq.a6": "Três metros cabem na maioria dos ambientes; seis metros são o padrão Snellen. O importante é medir uma vez e voltar sempre ao mesmo ponto.",
    "faq.q7": "O que é o teste da E giratória?",
    "faq.a7": "Uma E cuja abertura aponta para uma de quatro direções. Em vez de nomear letras, você diz para onde aponta. É usado com quem não lê o alfabeto latino e em muitos exames de profesional.",
    "faq.q8": "Meus resultados ficam guardados em algum lugar?",
    "faq.a8": "Só neste navegador. Não há contas nem envios. Você pode apagá-los quando quiser.",
