    "faq.q9": "O que é o teste duocromático?",
    "faq.a9": "As mesmas letras aparecem sobre fundo vermelho e verde. Se parecerem mais nítidas no vermelho, o seu olho foca ligeiramente à frente da retina (miopia); no verde, atrás (hipermetropia). Os óticos usam-no há um século para afinar a graduação.",
    "faq.q10": "Isto diz-me a minha graduação?",
    "faq.a10": "Não. Os testes de refração e astigmatismo dão apenas uma indicação da direção do erro. Só um optometrista qualificado, com foróptero e lentes de prova, pode emitir uma receita.",
    "faq.q11": "Porque não vejo a forma escondida?",
    "faq.a11": "Cerca de uma em cada dez pessoas não consegue ver estes autoestereogramas, e também falha se um olho for muito mais forte que o outro ou se não conseguir fundir as duas imagens. Não ver a forma não é, por si só, um diagnóstico — mas vale a pena referi-lo na próxima consulta.",
