    "states.official": "Sito ufficiale",
    "faq.q9": "Cos'è il test duocromatico rosso-verde?",
    "faq.a9": "Mostra le stesse lettere su sfondo rosso e verde. A causa della dispersione cromatica dell'occhio, la lunghezza d'onda rossa cade leggermente dietro la retina e quella verde davanti. Se vedi meglio sul rosso indicherà tendenza alla miopia, sul verde all'ipermetropia.",
    "faq.q10": "Questo test può fornirmi una gradazione per occhiali?",
    "faq.a10": "No. I test di rifrazione e astigmatismo danno unicamente un'indicazione qualitativa. Solo un optometrista o oculista qualificato con forottero e lenti di prova può determinare la gradazione corretta.",
    "faq.q11": "Perché non riesco a vedere la figura nascosta nello stereogramma?",
    "faq.a11": "Circa il 10% delle persone con vista sana non riesce a fondere gli stereogrammi a punti casuali. Può accadere anche in presenza di forte differenza visiva tra i due occhi.",
    "faq.q12": "Cosa succede se si fallisce il controllo della vista alla motorizzazione?",
    "faq.a12": "Non perdi la patente immediatamente. L'esaminatore rilascia un modulo per una visita specialistica da un oculista, che certificherà la vista e le eventuali lenti necessarie.",
    "faq.q13": "Posso indossare occhiali o lenti durante l'esame?",
    "faq.a13": "Sì, ed è consigliabile farlo se guidi abitualmente con correzione. Sulla patente verrà apposto il codice relativo all'obbligo di lenti (codice 01 in Europa).",
    "faq.q14": "Come si svolge solitamente la prova della vista per la patente?",
    "faq.a14": "Spesso si usa un ottotipo luminoso da lontano o un visore da tavolo. Si leggono le lettere occludendo un occhio alla volta, poi entrambi insieme, seguiti da un controllo per i colori e per il campo visivo.",
    "faq.q15": "È possibile sostenere la visita medica della patente online?",
    "faq.a15": "No. La visita medica per il rilascio o rinnovo della patente deve avvenire di persona davanti a un medico abilitato. Il test online è solo per tua preparazione personale.",
    "faq.q16": "Cosa portare con sé alla visita?",
    "faq.a16": "Porta gli occhiali da vista abituali, le lenti a contatto con relativo contenitore, un documento di identità e l'eventuale documentazione medica su interventi o patologie pregresse.",
    "faq.q17": "Come superare la prova della vista?",
    "faq.a17": "Non cercare di memorizzare le lettere: i tabelloni vengono ruotati. La preparazione efficace consiste nell'esercitare la procedura e assicurarsi di avere occhiali con gradazione corretta e aggiornata.",
    "faq.q18": "Perché si testa ciascun occhio separatamente se si guida con entrambi?",
    "faq.a18": "Perché le normative stabiliscono un'acuità minima sia per l'occhio migliore sia per l'occhio peggiore, per evitare che un occhio dominante nasconda un deficit grave dell'altro.",
    "faq.q19": "Quali prescrizioni o limitazioni possono essere annotate sulla patente?",
    "faq.a19": "L'obbligo di lenti (codice armonizzato UE 01) è la più frequente. Altre limitazioni possono riguardare la guida solo diurna, specchietti supplementari o limitazioni di velocità.",
    "faq.q20": "Come rimuovere l'obbligo di lenti dalla patente?",
    "faq.a20": "Se ti sei sottoposto a chirurgia refrattiva (es. LASIK) o la tua vista è migliorata, dovrai effettuare una visita medica ufficiale per verificare la nuova acuità a occhi nudi e aggiornare il documento.",
    "gen.hero.title": "Verifica la tua <em>vista online</em>, occhio per occhio.",
    "gen.hero.lede": "Calibra lo schermo, posizionati alla giusta distanza, copri un occhio alla volta e leggi la riga più piccola. Dodici test visivi, occhio per occhio, in circa dieci minuti.",
    "gen.checks.title": "Dodici test per distanza, colore e visione ravvicinata",
