    "faq.kicker": "質問",
    "faq.title": "始める前に",
    "faq.q1": "スマホで視力検査できますか？",
    "faq.a1": "はい、無料で簡易視力検査ができます。画面を調整し、片目ずつ行います。公式な医療診断ではありません。",
    "faq.q2": "眼科受診の代わりになりますか？",
    "faq.a2": "いいえ。画面では診断も処方もできません。気になる結果は眼科へ相談してください。",
    "faq.q3": "運転に必要な視力は？",
    "faq.a3": "日本では普通免許で両眼0.7以上かつ各眼0.3以上が目安です。運転免許更新時の視力検査の練習としてお使いください。米国では両目20/40が無制限の目安です。",
    "faq.q4": "眼鏡やコンタクトはつけたままですか？",
    "faq.a4": "はい。運転時の条件で受けてください。運転免許の視力検査も矯正視力で確認し、免許には条件が付きます。",
    "faq.q5": "画面の調整はなぜ必要ですか？",
    "faq.a5": "文字寸法をmmで計算するためです。未調整の20/40は実寸ではありません。銀行カードで倍率を合わせます。",
    "faq.q6": "距離はどれくらいですか？",
    "faq.a6": "3mは室内向け、6mはスネレン標準です。一度測り、毎回同じ位置に戻ることが大切です。",
    "faq.q7": "切れ目E検査とは？",
    "faq.a7": "Eの切れ目方向を答える検査です。文字を読まず方向で答え、事業用試験でも使われます。",
    "faq.q8": "結果は保存されますか？",
    "faq.a8": "このブラウザのみです。アカウントも送信もありません。いつでも消去できます。",
