    "faq.q9": "二色テストとは？",
    "faq.a9": "同じ文字を赤と緑背景で見比べます。赤が鮮明なら網膜手前で焦点する近視寄り、緑なら網膜後方の遠視寄りです。処方調整に長く使われています。",
    "faq.q10": "処方度数が分かりますか？",
    "faq.a10": "いいえ。屈折と乱視は方向の目安のみです。処方はフォロプターと試験レンズを持つ眼科医のみが発行できます。",
    "faq.q11": "隠し形が見えません。",
    "faq.a11": "約10人に1人は正常でも見えず、左右差や融像不良でも失敗します。単独で診断にはなりませんが次回受診で伝えてください。",
    "faq.q12": "米国の試験に落ちたらどうなりますか？",
    "faq.a12": "その場で失格にはなりません。眼科用紙を渡され、受診して再検査します。加州DL-62やNYのMV-619などが例です。",
    "faq.q13": "眼鏡やコンタクトで受けられますか？",
    "faq.a13": "はい、運転時と同じ条件で受けてください。矯正で合格すると免許に条件が付きます。読書用のみでは遠見に足りません。",
    "faq.q14": "米国の視力検査はどんな内容ですか？",
    "faq.a14": "Optec1000等の卓上器で片目ずつ数字行を読み、側方フラッシュと赤緑黄の色確認を行います。",
    "faq.q15": "米国の視力検査はオンラインでできますか？",
    "faq.a15": "いいえ、NYの登録制度を除き対面のみです。オンラインは練習用です。",
    "faq.q16": "不合格が心配なら何を持参しますか？",
    "faq.a16": "眼鏡やコンタクト、処方箋、身分証を持参してください。不合格後は医師記入済み用紙を持参します。",
    "faq.q17": "米国の視力検査に通るコツは？",
    "faq.a17": "表の暗記ではなく手順の習得です。表は差し替えられます。ランダム文字での練習が有効です。",
    "faq.q18": "両目運転なのになぜ片目ずつ隠しますか？",
    "faq.a18": "州基準は両目と片目の両方があるためです。弱い目が強い目に隠れるため、片目ずつ分けて確認します。",
    "faq.q19": "免許の条件には何がありますか？",
    "faq.a19": "矯正レンズ、日中のみ、屋外ミラーが代表例です。テキサスは20/60から20/70帯で45mph制限が付きます。",
    "faq.q20": "眼鏡条件の解除はどうしますか？",
    "faq.a20": "後日に裸眼で合格するか、LASIK後に再検査します。NYは登録制度での提出も可能です。",
