    "cdl.kicker": "Профессиональные права",
    "cdl.title": "Требования для профессиональных категорий водителей",
    "cdl.body": "Водители грузового и пассажирского транспорта проходят более строгий контроль: раздельная проверка каждого глаза, широкое поле зрения и точное различение сигналов светофора.",
    "cdl.l1": "Не менее 20/40 (0,5–0,7) для каждого глаза раздельно и вместе",
    "cdl.l2": "Горизонтальное поле зрения не менее 70° для каждого глаза",
    "cdl.l3": "Безошибочное различение красного, зеленого и желтого цветов",
