    "cdl.cardTitle": "Профессиональный водитель?",
    "cdl.cardBody": "Проверьте остроту зрения, периферию и цветовосприятие по стандартам для коммерческих категорий.",
    "faq.kicker": "Частые вопросы",
    "faq.title": "Перед началом тестирования",
    "faq.q1": "Можно ли проверить зрение онлайн с телефона или компьютера?",
    "faq.a1": "Да, данный сервис позволяет выполнить предварительную проверку дома при условии точной калибровки экрана и соблюдения дистанции. Однако он не заменяет визит к врачу.",
    "faq.q2": "Насколько точен этот онлайн-тест?",
    "faq.a2": "Калибровка по банковской карте обеспечивает физически точный размер оптотипов на экране. Тем не менее освещение, блики и контрастность дисплея могут вносить погрешность.",
    "faq.q3": "Что означает стандарт 20/40?",
    "faq.a3": "Это означает, что с расстояния 20 футов (6 м) вы видите то, что человек с нормальным зрением различает с 40 футов (12 м). Примерный эквивалент — 0,5 по десятичной шкале, обычный минимум для вождения без ограничений.",
    "faq.q4": "Зачем калибровать экран пластиковой картой?",
    "faq.a4": "Все банковские и идентификационные карты формата ISO имеют стандартную ширину 85,6 мм. Это позволяет скрипту точно перевести миллиметры в пиксели вашего экрана.",
    "faq.q5": "Что делать, если тест показал снижение зрения?",
    "faq.a5": "Не переживайте: в большинстве случаев достаточно подобрать или обновить очки. Запишитесь на диагностику к оптометристу или офтальмологу.",
    "faq.q6": "Можно ли проходить тест в очках или контактных линзах?",
    "faq.a6": "Да. Если вы водите автомобиль или читаете в очках, проходите проверку в них, чтобы оценить остроту зрения с коррекцией.",
    "faq.q7": "Сохраняются ли мои результаты или персональные данные?",
    "faq.a7": "Нет. Все вычисления происходят исключительно на вашем устройстве. Никакие личные данные и результаты не передаются на сервер.",
    "faq.q8": "Дает ли этот тест официальную справку для водительских прав?",
    "faq.a8": "Нет. Это инструмент для тренировки и предварительной самопроверки. Официальное медицинское заключение выдает только лицензированная медицинская комиссия.",
    "footer.tagline": "Бесплатный тест для проверки зрения дома.",
    "footer.langs": "Доступно на английском, испанском, французском, немецком, португальском, итальянском, японском и русском языках.",
