    "states.official": "Официальный сайт",
    "faq.q9": "Что такое дуохромный красно-зеленый тест?",
    "faq.a9": "Одинаковые буквы проецируются на красный и зеленый фон. Из-за разницы преломления световых волн разной длины красные лучи фокусируются чуть глубже, а зеленые — ближе. Если буквы четче на красном, есть склонность к близорукости, на зеленом — к дальнозоркости.",
    "faq.q10": "Может ли этот сайт определить диоптрии для очков?",
    "faq.a10": "Нет. Тесты рефракции и астигматизма показывают лишь качественное направление отклонения. Точный рецепт с диоптриями и осью цилиндра подбирает только специалист с фороптором и пробными линзами.",
    "faq.q11": "Почему я не могу разглядеть фигуру на стереограмме?",
    "faq.a11": "Около 10% людей с нормальным зрением испытывают трудности с автостереограммами. Также просмотр не удается при заметной разнице в остроте зрения между глазами или нарушении бинокулярного слияния.",
    "faq.q12": "Что происходит при непрохождении проверки зрения для водительских прав?",
    "faq.a12": "Права не аннулируются сразу. Водителю выдается направление к врачу-офтальмологу для углубленной проверки и назначения соответствующей оптической коррекции.",
    "faq.q13": "Разрешено ли проходить тест в очках или линзах?",
    "faq.a13": "Да, если вы обычно управляете автомобилем в очках или линзах, проходить комиссию нужно именно в них. В удостоверении появится отметка об обязательной оптической коррекции (отметка GCL / очки или линзы обязательны).",
    "faq.q14": "Как проходит проверка зрения в отделении?",
    "faq.a14": "Обычно используют настольный аппарат (визиотест) или настенную таблицу. Экзаменатор просит прочитать строку каждым глазом по отдельности, затем двумя глазами, после чего проверяет поля зрения и световые сигналы.",
    "faq.q15": "Можно ли пройти официальную медкомиссию онлайн?",
    "faq.a15": "Нет. Официальный осмотр для водительского удостоверения проводится очно лицензированными врачами. Онлайн-тест служит исключительно для домашней самопроверки.",
    "faq.q16": "Что взять с собой на медицинский осмотр?",
    "faq.a16": "Возьмите используемые очки или контейнер с линзами, паспорт, а также выписки об операциях на глазах (например, лазерной коррекции), если они проводились.",
    "faq.q17": "Как успешно пройти проверку зрения?",
    "faq.a17": "Не заучивайте таблицы наизусть: порядок букв регулярно меняют. Главное — выспаться, снять зрительное напряжение перед приемом и своевременно обновить очки, если зрение изменилось.",
    "faq.q18": "Зачем закрывать один глаз, если мы всегда смотрим двумя?",
    "faq.a18": "Потому что стандарты безопасности устанавливают требования как для каждого глаза отдельно, так и для обоих вместе. При двух открытых глазах сильный глаз может полностью маскировать серьезное ухудшение второго глаза.",
    "faq.q19": "Какие ограничения могут внести в водительское удостоверение?",
    "faq.a19": "Самая частая отметка — вождение только в очках или линзах (GCL). В ряде стран также встречаются ограничения на вождение только в светлое время суток или требование обязательных дополнительных зеркал.",
    "faq.q20": "Как снять отметку об очках в водительских правах?",
    "faq.a20": "Если после операции (например, LASIK) или восстановления зрение нормализовалось, нужно пройти медицинскую комиссию заново и подтвердить зрение без очков, после чего права заменяются без отметки.",
